import logging
import math
import random
import sys

import quintessa

logger = logging.getLogger("inversion_sampler")


class StandardNormal:
    # Density and distribution function of the standard normal.
    def pdf(self, x):
        return math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)

    def cdf(self, x):
        return 0.5 * (1.0 + math.erf(x / math.sqrt(2)))


def build_sampler(dist, seed):
    # Attach a seeded uniform source to the inversion sampler.
    uniform_source = random.Random(seed)
    return quintessa.InversionSampler(dist, random_state=uniform_source)


def measure_error(sampler, sample_size):
    # Estimate the approximation error over a number of test points.
    report = sampler.error_report(sample_size=sample_size)
    return {"max_error": report.max_error, "mean_abs_error": report.mean_abs_error}


def main(argv):
    logging.basicConfig(level=logging.INFO)
    sample_size = int(argv[1]) if len(argv) > 1 else 100_000
    sampler = build_sampler(StandardNormal(), seed=42)
    logger.info("error: %s", measure_error(sampler, sample_size))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

