import argparse
import logging
import sys

import argcheckone

logger = logging.getLogger("validacion")


@argcheckone.enforce
def repetir(texto: str, veces: int, *, separador: bytes = b"") -> bytes:
    """Repite el texto la cantidad de veces indicada, unido por el separador."""
    codificado = texto.encode()
    return separador.join(codificado for _ in range(veces))


def ejemplos() -> None:
    print(repetir("hola", 3))
    print(repetir("x", "4", separador=b" "))
    try:
        repetir("hola", "incorrecto")
    except argcheckone.CheckError as error:
        logger.warning("Argumento inválido: %s", error)
        print(error)


def parse_args(argv):
    parser = argparse.ArgumentParser(description="Demostración de validación de argumentos")
    parser.add_argument("--quiet", action="store_true", help="Solo mostrar advertencias")
    return parser.parse_args(argv)


def main(argv=None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    logging.basicConfig(level=logging.INFO)
    if args.quiet:
        logger.setLevel(logging.WARNING)
    ejemplos()
    return 0


if __name__ == "__main__":
    sys.exit(main())

import argparse
import logging
import sys
from pathlib import Path

import blobmeasure

logger = logging.getLogger("blob_size")


def read_image_bytes(path: Path) -> bytes:
    with path.open("rb") as handle:
        return handle.read()


def print_dimensions(data: bytes) -> None:
    with blobmeasure.Picture(blob=data) as picture:
        print("width =", picture.width)
        print("height =", picture.height)


def parse_args(argv):
    parser = argparse.ArgumentParser(description="Print the size of an image in memory")
    parser.add_argument("image", type=Path, nargs="?", default=Path("pikachu.png"))
    return parser.parse_args(argv)


def main(argv=None) -> int:
    logging.basicConfig(level=logging.INFO)
    args = parse_args(sys.argv[1:] if argv is None else argv)
    try:
        data = read_image_bytes(args.image)
    except OSError as exc:
        logger.error("No se pudo leer %s: %s", args.image, exc)
        return 1
    print_dimensions(data)
    return 0


if __name__ == "__main__":
    sys.exit(main())

import logging
import os
import sys

import jobtracer

logger = logging.getLogger("job_tracer")
JOB_BROKER = os.environ.get("JOBTRACER_BROKER", "memory://")


class DebugJob(jobtracer.Job):
    """Job base class that prints its name and request id before each run."""

    def __call__(self, *args, **kwargs):
        print("TASK STARTING: {0.name}[{0.request.id}]".format(self))
        return self.run(*args, **kwargs)


@jobtracer.register(parent=DebugJob)
def add(x, y):
    """Sample job that adds two numbers."""
    return x + y


def main() -> int:
    logging.basicConfig(level=logging.INFO)
    jobtracer.configure(broker=JOB_BROKER)
    result = add.dispatch(2, 3)
    logger.info("Job result: %s", result)
    return 0


if __name__ == "__main__":
    sys.exit(main())

