import logging
import os
import sys

import testrigkit

logger = logging.getLogger("conn_tests")
DEFAULT_CONFIG = {"user": "admin", "database": "prod"}
VERBOSE = bool(os.environ.get("TESTRIG_VERBOSE"))


def create_connection_string() -> str:
    """Build a connection string from the default configuration."""
    return f"User Id={DEFAULT_CONFIG['user']}; Location={DEFAULT_CONFIG['database']};"


@testrigkit.fixture
def mock_test_user(override):
    """Set the DEFAULT_CONFIG user to test_user."""
    override.item(DEFAULT_CONFIG, "user", "test_user")


@testrigkit.fixture
def mock_test_database(override):
    """Set the DEFAULT_CONFIG database to test_db."""
    override.item(DEFAULT_CONFIG, "database", "test_db")


@testrigkit.fixture
def mock_missing_default_user(override):
    """Remove the user key from DEFAULT_CONFIG."""
    override.remove_item(DEFAULT_CONFIG, "user", strict=False)


def test_connection(mock_test_user, mock_test_database):
    expected = "User Id=test_user; Location=test_db;"
    assert create_connection_string() == expected


def test_missing_user(mock_missing_default_user):
    with testrigkit.expect_error(KeyError):
        create_connection_string()


def main() -> int:
    logging.basicConfig(level=logging.INFO)
    passed = testrigkit.run_module(sys.modules[__name__], verbose=VERBOSE)
    logger.info("Tests ejecutados: %s", passed)
    return 0 if passed else 1


if __name__ == "__main__":
    sys.exit(main())

